class Solution {
    public int numComponents(ListNode head,int[] nums){
        Set<Integer> selected=new HashSet<>();
        for(int value:nums)selected.add(value);
        int answer=0;
        for(ListNode node=head;node!=null;node=node.next)if(selected.contains(node.val)&&(node.next==null||!selected.contains(node.next.val)))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numComponents(head:ListNode?,nums:IntArray):Int{
        val selected=nums.toSet();
        var answer=0;
        var node=head;
        while(node!=null){
            if(node.`val` in selected&&(node.next==null||node.next!!.`val` !in selected))answer++;
            node=node.next
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int numComponents(ListNode* head,vector<int>& nums){
        unordered_set<int> selected(nums.begin(),nums.end());
        int answer=0;
        for(ListNode* node=head;node;node=node->next)if(selected.count(node->val)&&(!node->next||!selected.count(node->next->val)))++answer;
        return answer;
    }
};
